B=(0,1.2);
C=(1.6,1.3);
D=(0.8,0);
E=B-(A-D);
F=C-(A-D);
G=B+(C-A);

draw(E--D--F--C--G--B--A--D);
draw(A--C); draw(E--B);

a=(1/3)*D+(2/3)*E;
c=(2/3)*D+(1/3)*E;
